#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <string.h>

#define MAX_MSG_SIZE 128

/*
 * Test data
 */
static char data_char = 'A';
static int data_int = 123;
static struct {
    char a;
    int b;
} data_struct = { 'B', 456 };
static char data_long_str[MAX_MSG_SIZE] = "This is a long string for testing purposes.";

static void *data_ptr[] = {
    &data_char,
    &data_int,
    &data_struct,
    data_long_str
};

static size_t data_size[] = {
    sizeof(data_char),
    sizeof(data_int),
    sizeof(data_struct),
    sizeof(data_long_str)
};

enum info_type {
    INFO_TYPE_CHAR,
    INFO_TYPE_INT,
    INFO_TYPE_STRUCT,
    INFO_TYPE_LONG_STR,
    INFO_TYPE_COUNT
};

/*
 * Helper functions
 */
static void tmbox_put(struct k_mbox *mbox, enum info_type type, k_timeout_t timeout)
{
    struct k_mbox_msg msg;

    msg.info = type;
    msg.size = data_size[type]; /* Fix: Use actual data size */
    msg.tx_data = data_ptr[type];
    msg.tx_block = 1;
    msg.rx_t = K_ANY;

    k_mbox_put(mbox, &msg, timeout);
}

static void tmbox_async_put(struct k_mbox *mbox, enum info_type type, k_timeout_t timeout)
{
    struct k_mbox_async_msg async_msg;

    k_mbox_async_init(&async_msg);

    /* Fix: Use actual data size */
    k_mbox_async_put(mbox, &async_msg, timeout, data_ptr[type], data_size[type]);
}

static void tmbox_get(struct k_mbox *mbox, enum info_type type)
{
    struct k_mbox_msg mmsg;
    char buffer[MAX_MSG_SIZE];
    int ret;

    ret = k_mbox_get(mbox, &mmsg, buffer, sizeof(buffer), K_FOREVER);
    zassert_equal(ret, 0, "k_mbox_get failed");

    zassert_equal(mmsg.info, type, "mmsg.info not equal to type");
    zassert_equal(mmsg.rx_t, K_ANY, "mmsg.rx_t not equal to K_ANY");

    /* Fix: Compare received size with actual data size, not pointer size */
    zassert_equal(mmsg.size, data_size[type], "mmsg.size not equal to expected size");

    zassert_mem_equal(buffer, data_ptr[type], mmsg.size, "Received data mismatch");
}

/*
 * Test cases
 */

/* Test defining multiple mailboxes */
ZTEST(mbox_api, test_define_multi_mbox)
{
    K_MBOX_DEFINE(mbox1);
    K_MBOX_DEFINE(mbox2);

    /* Just ensure they can be defined without compile errors */
    zassert_true(true, "Should not fail");
}

/* Test async put with multiple messages */
ZTEST(mbox_api, test_mbox_async_multiple_put)
{
    struct k_mbox mbox;
    k_mbox_init(&mbox);

    for (int i = 0; i < 3; i++) {
        struct k_mbox_async_msg async_msg;
        k_mbox_async_init(&async_msg);
        k_mbox_async_put(&mbox, &async_msg, K_NO_WAIT, NULL, 0);
    }

    for (int i = 0; i < 3; i++) {
        struct k_mbox_msg mmsg;
        k_mbox_get(&mbox, &mmsg, NULL, 0, K_NO_WAIT);
        zassert_equal(mmsg.size, 0, "mmsg.size not 0");
    }
}

/* Test async put and get with blocking */
ZTEST(mbox_api, test_mbox_async_put_get_block)
{
    struct k_mbox mbox;
    k_mbox_init(&mbox);

    struct k_mbox_async_msg async_msg;
    k_mbox_async_init(&async_msg);

    k_mbox_async_put(&mbox, &async_msg, K_NO_WAIT, NULL, 0);

    struct k_mbox_msg mmsg;
    k_mbox_get(&mbox, &mmsg, NULL, 0, K_FOREVER);
    zassert_equal(mmsg.size, 0, "mmsg.size not 0");
}

/* Test async put and get with buffer */
ZTEST(mbox_api, test_mbox_async_put_get_buffer)
{
    struct k_mbox mbox;
    k_mbox_init(&mbox);

    for (enum info_type type = 0; type < INFO_TYPE_COUNT; type++) {
        tmbox_async_put(&mbox, type, K_NO_WAIT);
        tmbox_get(&mbox, type);
    }
}

/* Test async put and get with buffer and timeout */
ZTEST(mbox_api, test_mbox_async_put_get_buffer_timeout)
{
    struct k_mbox mbox;
    k_mbox_init(&mbox);

    for (enum info_type type = 0; type < INFO_TYPE_COUNT; type++) {
        tmbox_async_put(&mbox, type, K_MSEC(100)); /* Use a timeout */
        tmbox_get(&mbox, type);
    }
}

/* Test async put and get with buffer and timeout, but no receiver */
ZTEST(mbox_api, test_mbox_async_put_get_buffer_timeout_no_receiver)
{
    struct k_mbox mbox;
    k_mbox_init(&mbox);

    struct k_mbox_async_msg async_msg;
    k_mbox_async_init(&async_msg);

    /* Put with a timeout, but no receiver will get it. */
    /* This should return -EAGAIN if the timeout expires. */
    int ret = k_mbox_async_put(&mbox, &async_msg, K_MSEC(10), data_ptr[INFO_TYPE_CHAR], data_size[INFO_TYPE_CHAR]);
    zassert_equal(ret, -EAGAIN, "k_mbox_async_put should return -EAGAIN");

    /* Ensure no message is left in the mailbox */
    struct k_mbox_msg mmsg;
    ret = k_mbox_get(&mbox, &mmsg, NULL, 0, K_NO_WAIT);
    zassert_equal(ret, -EAGAIN, "k_mbox_get should return -EAGAIN");
}

/* Test async put and get with buffer and timeout, receiver gets it */
ZTEST(mbox_api, test_mbox_async_put_get_buffer_timeout_receiver)
{
    struct k_mbox mbox;
    k_mbox_init(&mbox);

    struct k_mbox_async_msg async_msg;
    k_mbox_async_init(&async_msg);

    /* Put with a timeout, a receiver will get it immediately. */
    int ret = k_mbox_async_put(&mbox, &async_msg, K_MSEC(100), data_ptr[INFO_TYPE_CHAR], data_size[INFO_TYPE_CHAR]);
    zassert_equal(ret, 0, "k_mbox_async_put failed");

    tmbox_get(&mbox, INFO_TYPE_CHAR);
}

/* Test async put and get with buffer and timeout, receiver gets it after delay */
static K_THREAD_STACK_DEFINE(receiver_stack, 512);
static struct k_thread receiver_thread;
static struct k_mbox *g_mbox;
static enum info_type g_info_type;

void receiver_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_sleep(K_MSEC(50)); /* Simulate some delay before getting */
    tmbox_get(g_mbox, g_info_type);
}

ZTEST(mbox_api, test_mbox_async_put_get_buffer_timeout_receiver_delay)
{
    struct k_mbox mbox;
    k_mbox_init(&mbox);

    g_mbox = &mbox;
    g_info_type = INFO_TYPE_INT;

    k_thread_create(&receiver_thread, receiver_stack,
                    K_THREAD_STACK_SIZEOF(receiver_stack),
                    receiver_entry, NULL, NULL, NULL,
                    K_PRIO_PREEMPT(5), 0, K_NO_WAIT);

    k_thread_name_set(&receiver_thread, "mbox_receiver");

    struct k_mbox_async_msg async_msg;
    k_mbox_async_init(&async_msg);

    /* Put with a timeout, receiver will get it after a delay. */
    /* The put operation should block until the receiver gets it. */
    int ret = k_mbox_async_put(&mbox, &async_msg, K_MSEC(200), data_ptr[INFO_TYPE_INT], data_size[INFO_TYPE_INT]);
    zassert_equal(ret, 0, "k_mbox_async_put failed");

    k_thread_join(&receiver_thread, K_FOREVER);
}

ZTEST_SUITE(mbox_api, NULL, NULL, NULL, NULL, NULL);
